export type PreparationKey = keyof typeof messages;
export type PreparationLanguage = 'zh-CN' | 'zh-TW' | 'en' | 'ja' | 'ko' | 'th';
const languages: PreparationLanguage[] = ['zh-CN', 'zh-TW', 'en', 'ja', 'ko', 'th'];
export const preparationTranslations = Object.fromEntries(languages.map((language, index) => [
  language, Object.fromEntries(Object.entries(messages).map(([key, values]) => [key, values[index]]))
])) as Record<PreparationLanguage, Record<PreparationKey, string>>;

